using System;using System.IO;using System.Linq;using System.Text;using System.Collections.Generic;using System.Windows.Forms;
namespace ScoreModern {
 public static class NativeScoreIdentity {
  public sealed class Data {public string Path;public uint Serial;}
  static readonly Dictionary<string,string> selected=new Dictionary<string,string>(StringComparer.OrdinalIgnoreCase);
  public static Func<string[],string> SelectionForTests;
  static string Key(string folder){string full=System.IO.Path.GetFullPath(folder);return full.Length==System.IO.Path.GetPathRoot(full).Length?full:full.TrimEnd(System.IO.Path.DirectorySeparatorChar);}
  static string Settings{get{return "dat";}}
  public static bool TryRead(string path,out Data info){info=null;try{byte[] b=File.ReadAllBytes(path);if(b.Length<10464)return false;uint first=BitConverter.ToUInt32(b,0),second=BitConverter.ToUInt32(b,4);if(first<1000000||first>9999999||second<1000000||second>9999999||BitConverter.ToSingle(b,8)!=0||BitConverter.ToSingle(b,12)!=100)return false;int prior=0;for(int n=0;n<46;n++){int word=BitConverter.ToUInt16(b,9422+n*2);if(word<1||word>476||word<prior)return false;prior=word;}info=new Data{Path=System.IO.Path.GetFullPath(path),Serial=first};return true;}catch(IOException){return false;}catch(UnauthorizedAccessException){return false;}}
  public static void Load(){try{if(!NativeSettings.Exists(Settings))return;string[] rows=NativeSettings.ReadAllLines(Settings);for(int i=0;i+1<rows.Length;i+=2)selected[Key(rows[i])]=rows[i+1];}catch(IOException){}catch(ArgumentException){}}
  static void Save(){var lines=new List<string>();foreach(var pair in selected){lines.Add(pair.Key);lines.Add(pair.Value);}NativeSettings.WriteAllText(Settings,String.Join("\n",lines)+"\n");}
  public static void Select(string folder,string path,bool save){Data info;if(!String.Equals(Key(folder),Key(System.IO.Path.GetDirectoryName(System.IO.Path.GetFullPath(path))),StringComparison.OrdinalIgnoreCase)||!TryRead(path,out info))throw new InvalidDataException("Select a verified serial-bearing DAT from this LIB folder.");selected[Key(folder)]=info.Path;if(save)Save();}
  static string Choose(string folder,Data[] files){using(var dialog=new ScoreDialog("serial-dat"){Text="Select SCORE serial DAT",Width=700,Height=340,StartPosition=FormStartPosition.CenterScreen}){var help=new Label{Dock=DockStyle.Top,Height=55,Text="Several serial-bearing DAT files are present. Select the file to use for this LIB."};var list=new ListBox{Dock=DockStyle.Fill};foreach(var file in files)list.Items.Add(System.IO.Path.GetFileName(file.Path)+" — serial "+file.Serial);var buttons=new FlowLayoutPanel{Dock=DockStyle.Bottom,Height=40,FlowDirection=FlowDirection.RightToLeft};var cancel=new Button{Text="Cancel",DialogResult=DialogResult.Cancel};var use=new Button{Text="Use selected DAT",Width=150,Enabled=false};list.SelectedIndexChanged+=(s,e)=>use.Enabled=list.SelectedIndex>=0;use.Click+=(s,e)=>dialog.DialogResult=DialogResult.OK;buttons.Controls.Add(cancel);buttons.Controls.Add(use);dialog.Controls.Add(list);dialog.Controls.Add(help);dialog.Controls.Add(buttons);dialog.CancelButton=cancel;dialog.AcceptButton=use;return dialog.ShowDialog()==DialogResult.OK?files[list.SelectedIndex].Path:null;}}
  public static Data Require(string root,bool interactive){return Require(root,interactive,false);}
  public static Data Require(string root,bool interactive,bool forceChoice){string original=System.IO.Path.Combine(root,"LIB"),preferred=NativeLibraryLocation.DirectoryFor(root,false);if(NativeLibraryLocation.HasScor4Resources(root))original=preferred;foreach(string folder in new[]{preferred,original}.Select(System.IO.Path.GetFullPath).Distinct(StringComparer.OrdinalIgnoreCase)){if(!Directory.Exists(folder))continue;var files=new List<Data>();foreach(string file in Directory.GetFiles(folder,"*.DAT")){Data info;if(TryRead(file,out info))files.Add(info);}if(files.Count==0){if(!String.Equals(Key(folder),Key(original),StringComparison.OrdinalIgnoreCase)&&new[]{"SCOR3_10.DAT","SCOR4.DAT","SCR4_00.DAT"}.Any(name=>File.Exists(System.IO.Path.Combine(folder,name))))throw new InvalidDataException("The selected LIB contains no verified serial-bearing DAT. The previous LIB remains active.");continue;}string remembered;Data current;if(!forceChoice&&selected.TryGetValue(Key(folder),out remembered)&&files.Any(x=>String.Equals(x.Path,remembered,StringComparison.OrdinalIgnoreCase))&&TryRead(remembered,out current))return current;if(files.Count==1&&!forceChoice&&!selected.ContainsKey(Key(folder)))return files[0];string chosen=SelectionForTests!=null?SelectionForTests(files.Select(x=>x.Path).ToArray()):interactive?Choose(folder,files.ToArray()):null;if(chosen==null)throw new InvalidDataException("Choose which serial-bearing DAT to use in "+folder+" before starting SCORE Modern.");Select(folder,chosen,interactive);if(!TryRead(chosen,out current))throw new InvalidDataException("Selected DAT is no longer available.");return current;}throw new InvalidDataException("SCORE Modern cannot start without a verified serial-bearing DAT in LIB. Supply a compatible SCOR3_10.DAT, SCOR4.DAT or SCR4_00.DAT. Date/data-header files do not satisfy this requirement.");}
 }
}
